CREATE OR REPLACE FUNCTION public.guard_fold_links() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.pod_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.eye_pod_registry WHERE id=NEW.pod_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Pod must belong to the fold owner' USING ERRCODE='42501'; END IF; IF NEW.router_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.mesh_routers WHERE id=NEW.router_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Router must belong to the fold owner' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_fold_links BEFORE INSERT OR UPDATE OF pod_id, router_id, user_id ON public.pod_folds FOR EACH ROW EXECUTE FUNCTION public.guard_fold_links();
CREATE POLICY gunit_improvements_server_insert ON public.gunit_improvements AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (false);
CREATE POLICY gunit_improvements_server_update ON public.gunit_improvements AS RESTRICTIVE FOR UPDATE TO authenticated USING (false) WITH CHECK (false);